%% ============================================================
%  LOG DATA - OPEN DUCK MINI V2
%
%  Read CSV data generated by Python and redraw all figures
%  in MATLAB.
%
%  Folder structure:
%
%  matlab/
%  ├── log_data.m
%  └── data/
%      └── TH_1/
%          ├── left_contact_force.csv
%          ├── right_contact_force.csv
%          ├── joint_torques.csv
%          ├── joint_angles.csv
%          ├── velocity_x.csv
%          ├── velocity_y.csv
%          ├── left_swing_height.csv
%          ├── right_swing_height.csv
%          ├── sagittal_motion.csv
%          └── lateral_motion.csv
%
% =============================================================

clear;
clc;
close all;


%% ============================================================
% USER SETTINGS
% =============================================================

CASE_NAME = "TH_2";

% Current STS3215 actuator torque limit from MuJoCo XML
TORQUE_LIMIT = 3.23;      % [N.m]

% Figure settings
LINE_WIDTH = 1.5;
LIMIT_LINE_WIDTH = 1.2;
FONT_SIZE = 11;

% Set true if you want to save MATLAB .fig files automatically
SAVE_FIGURES = false;


%% ============================================================
% DATA PATH
% =============================================================

script_path = mfilename('fullpath');
script_dir = fileparts(script_path);

data_dir = fullfile( ...
    script_dir, ...
    "data", ...
    CASE_NAME);

if ~isfolder(data_dir)

    error( ...
        "Data folder does not exist: %s", ...
        data_dir);

end

fprintf("\n========================================\n");
fprintf("Loading data from:\n%s\n", data_dir);
fprintf("========================================\n\n");


%% ============================================================
% LOAD CSV FILES
% =============================================================

left_force = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "left_contact_force.csv"));

right_force = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "right_contact_force.csv"));

joint_torques = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "joint_torques.csv"));

joint_angles = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "joint_angles.csv"));

velocity_x = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "velocity_x.csv"));

velocity_y = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "velocity_y.csv"));

left_swing = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "left_swing_height.csv"));

right_swing = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "right_swing_height.csv"));

sagittal_motion = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "sagittal_motion.csv"));

lateral_motion = read_csv_safe( ...
    fullfile( ...
        data_dir, ...
        "lateral_motion.csv"));


%% ============================================================
% 1. SAGITTAL MOTION
% =============================================================

if ~isempty(sagittal_motion)

    figure( ...
        'Name', ...
        'Sagittal Motion', ...
        'Color', ...
        'w');

    hold on;

    plot( ...
        sagittal_motion.time_s, ...
        sagittal_motion.right_foot_x_m, ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        sagittal_motion.time_s, ...
        sagittal_motion.left_foot_x_m, ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        sagittal_motion.time_s, ...
        sagittal_motion.com_x_m, ...
        '--', ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        sagittal_motion.time_s, ...
        sagittal_motion.dcm_x_m, ...
        ':', ...
        'LineWidth', ...
        LINE_WIDTH + 0.3);

    xlabel('Time (s)');
    ylabel('X Position (m)');

    title('Sagittal Motion');

    legend( ...
        'Right foot', ...
        'Left foot', ...
        'CoM', ...
        'DCM', ...
        'Location', ...
        'best');

    grid on;
    box on;

    set(gca, ...
        'FontSize', ...
        FONT_SIZE);

    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "sagittal_motion.fig"));

    end

end


%% ============================================================
% 2. LATERAL MOTION
% =============================================================

if ~isempty(lateral_motion)

    figure( ...
        'Name', ...
        'Lateral Motion', ...
        'Color', ...
        'w');

    hold on;

    plot( ...
        lateral_motion.time_s, ...
        lateral_motion.right_foot_y_m, ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        lateral_motion.time_s, ...
        lateral_motion.left_foot_y_m, ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        lateral_motion.time_s, ...
        lateral_motion.com_y_m, ...
        '--', ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        lateral_motion.time_s, ...
        lateral_motion.dcm_y_m, ...
        ':', ...
        'LineWidth', ...
        LINE_WIDTH + 0.3);

    xlabel('Time (s)');
    ylabel('Y Position (m)');

    title('Lateral Motion');

    legend( ...
        'Right foot', ...
        'Left foot', ...
        'CoM', ...
        'DCM', ...
        'Location', ...
        'best');

    grid on;
    box on;

    set(gca, ...
        'FontSize', ...
        FONT_SIZE);

    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "lateral_motion.fig"));

    end

end


%% ============================================================
% 3. SWING FOOT HEIGHT
% =============================================================

if ...
    ~isempty(left_swing) ...
    && ...
    ~isempty(right_swing)

    figure( ...
        'Name', ...
        'Swing Foot Height', ...
        'Color', ...
        'w');

    hold on;

    plot( ...
        left_swing.time_s, ...
        left_swing.left_foot_z_m, ...
        'LineWidth', ...
        LINE_WIDTH);

    plot( ...
        right_swing.time_s, ...
        right_swing.right_foot_z_m, ...
        'LineWidth', ...
        LINE_WIDTH);

    xlabel('Time (s)');
    ylabel('Foot Height (m)');

    title('Swing Foot Height');

    legend( ...
        'Left foot', ...
        'Right foot', ...
        'Location', ...
        'best');

    grid on;
    box on;

    set(gca, ...
        'FontSize', ...
        FONT_SIZE);

    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "swing_foot_height.fig"));

    end

end


%% ============================================================
% 4. VELOCITY TRACKING - X
%
% Actual velocity:
% whole-body CoM velocity
% =============================================================

if ~isempty(velocity_x)

    figure( ...
        'Name', ...
        'Velocity Tracking X', ...
        'Color', ...
        'w');

    hold on;

    plot( ...
        velocity_x.time_s, ...
        velocity_x.desired_vx_m_s, ...
        '--', ...
        'LineWidth', ...
        LINE_WIDTH + 0.3);

    plot( ...
        velocity_x.time_s, ...
        velocity_x.actual_com_vx_m_s, ...
        'LineWidth', ...
        LINE_WIDTH);

    xlabel('Time (s)');
    ylabel('Velocity (m/s)');

    title('Sagittal Velocity Tracking');

    legend( ...
        'Desired V_x', ...
        'Actual CoM V_x', ...
        'Location', ...
        'best');

    grid on;
    box on;

    set(gca, ...
        'FontSize', ...
        FONT_SIZE);

    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "velocity_x.fig"));

    end

end


%% ============================================================
% 5. VELOCITY TRACKING - Y
%
% Actual velocity:
% whole-body CoM velocity
% =============================================================

if ~isempty(velocity_y)

    figure( ...
        'Name', ...
        'Velocity Tracking Y', ...
        'Color', ...
        'w');

    hold on;

    plot( ...
        velocity_y.time_s, ...
        velocity_y.desired_vy_m_s, ...
        '--', ...
        'LineWidth', ...
        LINE_WIDTH + 0.3);

    plot( ...
        velocity_y.time_s, ...
        velocity_y.actual_com_vy_m_s, ...
        'LineWidth', ...
        LINE_WIDTH);

    xlabel('Time (s)');
    ylabel('Velocity (m/s)');

    title('Lateral Velocity Tracking');

    legend( ...
        'Desired V_y', ...
        'Actual CoM V_y', ...
        'Location', ...
        'best');

    grid on;
    box on;

    set(gca, ...
        'FontSize', ...
        FONT_SIZE);

    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "velocity_y.fig"));

    end

end


%% ============================================================
% 6. CONTACT FORCE
%
% Row 1: Fx
% Row 2: Fy
% Row 3: Fz
%
% Column 1: Left foot
% Column 2: Right foot
% =============================================================

if ...
    ~isempty(left_force) ...
    && ...
    ~isempty(right_force)

    figure( ...
        'Name', ...
        'Contact Forces', ...
        'Color', ...
        'w');

    tiledlayout( ...
        3, ...
        2, ...
        'TileSpacing', ...
        'compact', ...
        'Padding', ...
        'compact');


    % --------------------------------------------------------
    % LEFT Fx
    % --------------------------------------------------------

    nexttile;

    plot( ...
        left_force.time_s, ...
        left_force.force_x_N, ...
        'LineWidth', ...
        LINE_WIDTH);

    ylabel('F_x (N)');
    title('Left Foot - F_x');

    grid on;
    box on;


    % --------------------------------------------------------
    % RIGHT Fx
    % --------------------------------------------------------

    nexttile;

    plot( ...
        right_force.time_s, ...
        right_force.force_x_N, ...
        'LineWidth', ...
        LINE_WIDTH);

    ylabel('F_x (N)');
    title('Right Foot - F_x');

    grid on;
    box on;


    % --------------------------------------------------------
    % LEFT Fy
    % --------------------------------------------------------

    nexttile;

    plot( ...
        left_force.time_s, ...
        left_force.force_y_N, ...
        'LineWidth', ...
        LINE_WIDTH);

    ylabel('F_y (N)');
    title('Left Foot - F_y');

    grid on;
    box on;


    % --------------------------------------------------------
    % RIGHT Fy
    % --------------------------------------------------------

    nexttile;

    plot( ...
        right_force.time_s, ...
        right_force.force_y_N, ...
        'LineWidth', ...
        LINE_WIDTH);

    ylabel('F_y (N)');
    title('Right Foot - F_y');

    grid on;
    box on;


    % --------------------------------------------------------
    % LEFT Fz
    % --------------------------------------------------------

    nexttile;

    plot( ...
        left_force.time_s, ...
        left_force.force_z_N, ...
        'LineWidth', ...
        LINE_WIDTH);

    xlabel('Time (s)');
    ylabel('F_z (N)');
    title('Left Foot - F_z');

    grid on;
    box on;


    % --------------------------------------------------------
    % RIGHT Fz
    % --------------------------------------------------------

    nexttile;

    plot( ...
        right_force.time_s, ...
        right_force.force_z_N, ...
        'LineWidth', ...
        LINE_WIDTH);

    xlabel('Time (s)');
    ylabel('F_z (N)');
    title('Right Foot - F_z');

    grid on;
    box on;

    sgtitle( ...
        'Reconstructed Contact Forces');

    set( ...
        findall( ...
            gcf, ...
            'Type', ...
            'axes'), ...
        'FontSize', ...
        FONT_SIZE);

    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "contact_forces.fig"));

    end

end


%% ============================================================
% 7. RECONSTRUCTED LEG JOINT TORQUES
%
% Current actuator torque limit:
%
%       -3.23 <= tau <= +3.23 N.m
%
% =============================================================

if ~isempty(joint_torques)

    joint_names = { ...
        'left_hip_yaw', ...
        'left_hip_roll', ...
        'left_hip_pitch', ...
        'left_knee', ...
        'left_ankle', ...
        'right_hip_yaw', ...
        'right_hip_roll', ...
        'right_hip_pitch', ...
        'right_knee', ...
        'right_ankle'};

    joint_titles = { ...
        'Left Hip Yaw', ...
        'Left Hip Roll', ...
        'Left Hip Pitch', ...
        'Left Knee', ...
        'Left Ankle', ...
        'Right Hip Yaw', ...
        'Right Hip Roll', ...
        'Right Hip Pitch', ...
        'Right Knee', ...
        'Right Ankle'};

    % Order plots as:
    %
    % Left          Right
    % Hip yaw       Hip yaw
    % Hip roll      Hip roll
    % Hip pitch     Hip pitch
    % Knee          Knee
    % Ankle         Ankle

    plot_order = [ ...
        1, 6, ...
        2, 7, ...
        3, 8, ...
        4, 9, ...
        5, 10];


    figure( ...
        'Name', ...
        'Leg Joint Torques', ...
        'Color', ...
        'w');

    tiledlayout( ...
        5, ...
        2, ...
        'TileSpacing', ...
        'compact', ...
        'Padding', ...
        'compact');


    for k = 1:length(plot_order)

        joint_index = ...
            plot_order(k);

        joint_name = ...
            joint_names{joint_index};

        variable_name = ...
            [joint_name, '_Nm'];

        if ~ismember( ...
                variable_name, ...
                joint_torques.Properties.VariableNames)

            warning( ...
                "Torque column not found: %s", ...
                variable_name);

            nexttile;

            title( ...
                joint_titles{joint_index});

            continue;

        end


        nexttile;

        hold on;


        % ----------------------------------------------------
        % Reconstructed torque
        % ----------------------------------------------------

        plot( ...
            joint_torques.time_s, ...
            joint_torques.(variable_name), ...
            'LineWidth', ...
            LINE_WIDTH);


        % ----------------------------------------------------
        % Upper torque limit
        % ----------------------------------------------------

        yline( ...
            +TORQUE_LIMIT, ...
            '--', ...
            'Upper limit', ...
            'LineWidth', ...
            LIMIT_LINE_WIDTH);


        % ----------------------------------------------------
        % Lower torque limit
        % ----------------------------------------------------

        yline( ...
            -TORQUE_LIMIT, ...
            '--', ...
            'Lower limit', ...
            'LineWidth', ...
            LIMIT_LINE_WIDTH);


        % ----------------------------------------------------
        % Zero line
        % ----------------------------------------------------

        yline( ...
            0, ...
            ':', ...
            'LineWidth', ...
            0.8);


        title( ...
            joint_titles{joint_index});

        ylabel( ...
            'Torque (N.m)');

        grid on;
        box on;


        if k >= 9

            xlabel( ...
                'Time (s)');

        end

    end


    sgtitle( ...
        'Reconstructed Leg Joint Torques');

    set( ...
        findall( ...
            gcf, ...
            'Type', ...
            'axes'), ...
        'FontSize', ...
        FONT_SIZE);


    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "joint_torques.fig"));

    end

end


%% ============================================================
% 8. LEG JOINT ANGLES
%
% This section is optional.
% It is plotted only when joint_angles.csv contains data.
% =============================================================

if ~isempty(joint_angles)

    joint_names = { ...
        'left_hip_yaw', ...
        'left_hip_roll', ...
        'left_hip_pitch', ...
        'left_knee', ...
        'left_ankle', ...
        'right_hip_yaw', ...
        'right_hip_roll', ...
        'right_hip_pitch', ...
        'right_knee', ...
        'right_ankle'};

    joint_titles = { ...
        'Left Hip Yaw', ...
        'Left Hip Roll', ...
        'Left Hip Pitch', ...
        'Left Knee', ...
        'Left Ankle', ...
        'Right Hip Yaw', ...
        'Right Hip Roll', ...
        'Right Hip Pitch', ...
        'Right Knee', ...
        'Right Ankle'};


    % Joint position limits from current MuJoCo XML [deg]
    lower_limit_deg = [ ...
        -30, ...
        -25, ...
        -70, ...
        -90, ...
        -90, ...
        -30, ...
        -25, ...
        -30, ...
        -90, ...
        -90];

    upper_limit_deg = [ ...
        +30, ...
        +25, ...
        +30, ...
        +90, ...
        +90, ...
        +30, ...
        +25, ...
        +70, ...
        +90, ...
        +90];


    plot_order = [ ...
        1, 6, ...
        2, 7, ...
        3, 8, ...
        4, 9, ...
        5, 10];


    figure( ...
        'Name', ...
        'Leg Joint Angles', ...
        'Color', ...
        'w');

    tiledlayout( ...
        5, ...
        2, ...
        'TileSpacing', ...
        'compact', ...
        'Padding', ...
        'compact');


    for k = 1:length(plot_order)

        joint_index = ...
            plot_order(k);

        joint_name = ...
            joint_names{joint_index};

        variable_name = ...
            [joint_name, '_rad'];


        nexttile;


        if ~ismember( ...
                variable_name, ...
                joint_angles.Properties.VariableNames)

            warning( ...
                "Joint-angle column not found: %s", ...
                variable_name);

            title( ...
                joint_titles{joint_index});

            continue;

        end


        hold on;


        % ----------------------------------------------------
        % Joint position
        % ----------------------------------------------------

        angle_deg = rad2deg( ...
            joint_angles.(variable_name));


        plot( ...
            joint_angles.time_s, ...
            angle_deg, ...
            'LineWidth', ...
            LINE_WIDTH);


        % ----------------------------------------------------
        % Joint limits
        % ----------------------------------------------------

        yline( ...
            lower_limit_deg(joint_index), ...
            '--', ...
            'Lower limit', ...
            'LineWidth', ...
            LIMIT_LINE_WIDTH);

        yline( ...
            upper_limit_deg(joint_index), ...
            '--', ...
            'Upper limit', ...
            'LineWidth', ...
            LIMIT_LINE_WIDTH);


        title( ...
            joint_titles{joint_index});

        ylabel( ...
            'Angle (deg)');

        grid on;
        box on;


        if k >= 9

            xlabel( ...
                'Time (s)');

        end

    end


    sgtitle( ...
        'Leg Joint Angles and Joint Limits');

    set( ...
        findall( ...
            gcf, ...
            'Type', ...
            'axes'), ...
        'FontSize', ...
        FONT_SIZE);


    if SAVE_FIGURES

        savefig( ...
            fullfile( ...
                data_dir, ...
                "joint_angles.fig"));

    end

end


%% ============================================================
% FINISHED
% =============================================================

fprintf("\n========================================\n");
fprintf("MATLAB plotting completed.\n");
fprintf("Case: %s\n", CASE_NAME);
fprintf("========================================\n\n");


%% ============================================================
% LOCAL FUNCTION
% =============================================================

function T = read_csv_safe(file_path)

    % --------------------------------------------------------
    % File does not exist
    % --------------------------------------------------------

    if ~isfile(file_path)

        warning( ...
            "CSV file does not exist:\n%s", ...
            file_path);

        T = table;

        return;

    end


    % --------------------------------------------------------
    % File exists but is empty
    % --------------------------------------------------------

    file_info = dir(file_path);

    if file_info.bytes == 0

        warning( ...
            "CSV file is empty:\n%s", ...
            file_path);

        T = table;

        return;

    end


    % --------------------------------------------------------
    % Read CSV
    % --------------------------------------------------------

    T = readtable( ...
        file_path, ...
        'VariableNamingRule', ...
        'preserve');


    % --------------------------------------------------------
    % Check empty table
    % --------------------------------------------------------

    if height(T) == 0

        warning( ...
            "CSV contains no samples:\n%s", ...
            file_path);

        T = table;

    end

end